 || TO_CLOB('            ter.REPORTNO,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            tep.ENTRUSTORGNAME,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            tep.TESTORGNAME,')
 || TO_CLOB(CHR(10))
