 || TO_CLOB(CHR(10))
 || TO_CLOB('            <include refid="com.sunwayworld.cloud.module.lcdp.base.persistent.mapper.LcdpBaseMapper.auditAuthorityWhereClause" />')
 || TO_CLOB(CHR(10))
 || TO_CLOB('        </where>')
 || TO_CLOB(CHR(10))
