 || TO_CLOB('<mapper namespace="emc.ProjectInfoModify.mapper.LcdpEmcProjectMapper">')
 || TO_CLOB(CHR(10))
 || TO_CLOB('    <select id="selectByCondition" parameterType="map" resultType="map">')
 || TO_CLOB(CHR(10))
 || TO_CLOB('        SELECT T.*')
 || TO_CLOB(CHR(10))
 || TO_CLOB('          FROM ')
 || TO_CLOB(CHR(10))
