 || TO_CLOB(CHR(10))
 || TO_CLOB('<mapper namespace="emc.equiptInOut.mapper.LcdpEmcEquiptIMapper">')
 || TO_CLOB(CHR(10))
 || TO_CLOB('    <select id="selectByCondition" parameterType="map" resultType="map">')
 || TO_CLOB(CHR(10))
 || TO_CLOB('        SELECT T.*')
 || TO_CLOB(CHR(10))
 || TO_CLOB('          FROM ')
 || TO_CLOB(CHR(10))
 || TO_CLOB('          (WITH equiptck AS(')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                SELECT ')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                teei.EQUIPTID,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                MAX(tcu.username) KEEP (DENSE_RANK FIRST ORDER BY teei.OPERATETIME DESC) as username,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                max(teei.OPERATETIME) AS OPERATETIME')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                FROM T_EMC_EQUIPT_INOUT teei ')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                LEFT JOIN T_CORE_USER tcu ON	tcu.id = teei.OPERATEUSERID')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                WHERE teei.OPERATETYPE = ''out''')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                GROUP BY teei.EQUIPTID')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            )')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            SELECT ')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                tee.*,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                equiptck.username AS username,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                equiptck.OPERATETIME AS OPERATETIME,')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                TRUNC(SYSDATE)-TRUNC(equiptck.OPERATETIME)+ 1 AS dates')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            FROM')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                T_EMC_EQUIPT tee')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            LEFT JOIN equiptck ON tee.ID = equiptck.EQUIPTID')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            WHERE')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                INOUTSTATUS = ''out''')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            <!-- ORDER BY OPERATETIME asc -->')
 || TO_CLOB(CHR(10))
 || TO_CLOB('        ) T')
 || TO_CLOB(CHR(10))
 || TO_CLOB('        <where>')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            <include refid="com.sunwayworld.framework.mybatis.mapper.GlobalMapper.appendWhereClausesIfPresent" />')
 || TO_CLOB(CHR(10))
 || TO_CLOB('            <if test=''authority_audit == "1"''>')
 || TO_CLOB(CHR(10))
 || TO_CLOB('                AND <include refid="com.sunwayworld.framework.mybatis.mapper.GlobalMapper.auditAuthorityWhereClause" />')
 || TO_CLOB(CHR(10))
